/**
 * @file Existing Port providers exposed as instance Capabilities.
 * @description Defines stable typed service keys and small provider factories
 * without replacing the public Port interfaces they carry.
 */
import type { Clock } from '../ports/clock';
import type { DownloadProvider } from '../ports/download';
import type { IdGenerator } from '../ports/id-generator';
import type { Logger } from '../ports/logger';
import type { PrintProvider } from '../ports/print';
import type { TextInputProvider } from '../ports/text-input';
import type { AnnotationRepository } from '../repository/annotation-repository';
import type { PdfThumbnailSurfaceProvider } from '../viewer/types';
import type { InkLayerCapability } from './contracts';
export { INKLAYER_CAPABILITY_SERVICE_KEYS } from './service-map';
export type { InkLayerCapabilityServiceKey, InkLayerCapabilityServiceMap } from './service-map';
/** Shared options for a single Port provider Capability. */
export interface InkLayerPortCapabilityOptions {
    /** Capability ID; defaults to the stable service key. */
    id?: string;
}
/** Ownership accepted only by the Repository provider. */
export interface AnnotationRepositoryCapabilityOptions extends InkLayerPortCapabilityOptions {
    /** Borrow by default, or transfer Repository destruction to this instance. */
    ownership?: 'borrowed' | 'owned';
}
/** Creates an instance Logger provider. */
export declare function createLoggerCapability(logger: Logger, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance Text Input provider. */
export declare function createTextInputCapability(provider: TextInputProvider, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance Annotation Repository provider with explicit ownership. */
export declare function createAnnotationRepositoryCapability(repository: AnnotationRepository, options?: AnnotationRepositoryCapabilityOptions): InkLayerCapability;
/** Creates an instance Print provider. */
export declare function createPrintCapability(provider: PrintProvider, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance Download provider. */
export declare function createDownloadCapability(provider: DownloadProvider, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance Clock provider. */
export declare function createClockCapability(clock: Clock, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance identifier generator provider. */
export declare function createIdGeneratorCapability(generator: IdGenerator, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance thumbnail surface provider. */
export declare function createThumbnailSurfaceCapability(provider: PdfThumbnailSurfaceProvider, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
/** Creates an instance Fetch provider used by Viewer Range loading. */
export declare function createFetchCapability(fetchImplementation: typeof globalThis.fetch, options?: InkLayerPortCapabilityOptions): InkLayerCapability;
